#!/usr/bin/env bash
# The 1001 Tester (mouli 2.2.0): unofficial libft tester (subject v19.3).
# Single-file installer.
#   bash install_mouli.sh              install or update (in ~/.mouli)
#   bash install_mouli.sh --uninstall  uninstall
# The rest of this file is the tester itself (tar.gz archive, base64 encoded).
set -e
if ! command -v python3 >/dev/null 2>&1; then
	echo "mouli: python3 not found (it is installed on 42 computers)." >&2
	exit 1
fi
TMP="$(mktemp -d "${TMPDIR:-/tmp}/mouli-install.XXXXXX")"
trap 'rm -rf "$TMP"' EXIT
sed '1,/^__ARCHIVE_MOULI__$/d' "$0" \
	| python3 -c 'import base64, sys; sys.stdout.buffer.write(base64.b64decode(sys.stdin.read()))' \
	| tar -xzf - -C "$TMP"
bash "$TMP/mouli/install.sh" "$@"
exit $?
